function resourceMenu(back){const c=panel('리소스 팩');text(c,'1.8 형식의 textures 폴더를 선택하면 지원되는 블록·아이템·버튼·핫바 텍스처를 적용합니다. 파일은 서버로 전송하지 않습니다.');text(c,'1.8.9 리소스팩 ZIP 또는 1.8.9.jar를 선택하거나, 압축을 푼 assets/minecraft/textures 폴더를 선택하세요.');const archive=document.createElement('input');archive.type='file';archive.accept='.zip,.jar';archive.onchange=async()=>{if(!archive.files[0])return;try{toast('텍스처 읽는 중…');const n=await importPack(art,await readTextureArchive(archive.files[0]));atlas.needsUpdate=true;heldId=-1;itemIconCache.clear();updateHotbar();toast(n+'개 텍스처 적용 및 저장');}catch(e){toast(e.message)}};c.append(archive);text(c,'업로드한 1.8.9 기본 리소스가 내장되어 자동 적용됩니다. 사용자 팩을 선택하면 지원 항목을 덮어씁니다.');const input=document.createElement('input');input.type='file';input.multiple=true;input.setAttribute('webkitdirectory','');input.onchange=async()=>{try{const n=await importPack(art,input.files);atlas.needsUpdate=true;heldId=-1;itemIconCache.clear();updateHotbar();toast(n+'개 텍스처 적용 및 저장');}catch(e){toast(e.message)}};c.append(input);row(c).append(button('내장 1.8.9 텍스처 복원',()=>{clearPack();save();location.reload()}),button('완료',()=>options(back)));}
