function itemName(k){const b=itemToBlock.get(k);return b?BLOCKS[b][0]:ko[k]||S.item(k)?.displayName||'빈 슬롯';}
const itemIconCache=new Map();
function itemIcon(k){const imported=itemTexture(k);if(imported&&customItemURLs.has(imported))return imported;const modeled=modelItemIcon(k);if(modeled)return modeled;if(imported)return imported;const b=itemToBlock.get(k);if(b)return art.icons[b];const model=modelItemIcon(k);if(model)return model;if(itemIconCache.has(k))return itemIconCache.get(k);const sprite=fallbackItemSprite(S.item(k)?.name||'');if(sprite){itemIconCache.set(k,sprite);return sprite;}const c=document.createElement('canvas');c.width=c.height=32;const g=c.getContext('2d'),d=S.item(k),name=d?.name||'',r=(color,x,y,w,h)=>{g.fillStyle=color;g.fillRect(x,y,w,h)};if(/sword|axe|shovel|hoe/.test(name)){const metal=name.startsWith('diamond')?'#63e5cf':name.startsWith('golden')?'#e4ca48':name.startsWith('iron')?'#ddd':name.startsWith('stone')?'#999':'#ac7d45';for(let i=0;i<17;i++)r('#493221',7+i,26-i,3,3);if(name.endsWith('sword')){for(let i=0;i<16;i++)r(metal,12+i,19-i,4,4);r('#8d7654',9,17,10,3);}else if(name.endsWith('pickaxe')){r(metal,8,3,18,4);r(metal,24,5,4,8);}else if(name.endsWith('axe')){r(metal,10,3,13,10);}else if(name.endsWith('shovel'))r(metal,19,3,8,9);else r(metal,10,3,16,4);}else if(name==='stick'){for(let i=0;i<19;i++)r('#936f40',6+i,27-i,3,3);}else if(/ingot|brick/.test(name)){r('#222',5,10,24,12);r(name.includes('gold')?'#e9c94f':name.includes('iron')?'#d7d9dd':'#bb7254',5,10,21,10);r('#ffffff66',7,11,17,2);}else if(/diamond|emerald|coal/.test(name)){const color=name==='diamond'?'#5ed9d8':name==='emerald'?'#53bc68':'#333';r('#222',9,5,15,19);r(color,7,7,18,14);r('#ffffff55',10,8,6,3);}else{const hue=(Number(S.parse(k)[0])*41)%360;r('#292929',6,5,21,23);r(`hsl(${hue},45%,58%)`,8,7,17,19);r('#ffffff55',9,8,11,3);g.fillStyle='#fff';g.font='bold 11px monospace';g.fillText((d?.displayName||'?').slice(0,2),9,22);}const url=c.toDataURL();itemIconCache.set(k,url);return url;}
function heldKey(){return state.slots[slot]?.key||null;}
function heldWorldBlock(){return itemToBlock.get(heldKey())||0;}
function syncState(next){state=next;slot=state.selected||0;hotbar=state.slots.slice(0,9).map(v=>itemToBlock.get(v?.key)||0);updateHotbar();updateVitals();if(screen==='game'&&state.hp<=0)death();if(['인벤토리','제작','화로','상자'].includes(screen))renderInventory();}
function operate(action){action.selected=slot;if(roomCode){transmit({type:'move',pos:[player.x,player.y,player.z,yaw,pitch]});transmit({type:'action',action});return true;}try{const ctx={get,set:setBlock,dimension:dimensionName,projectiles,players:[{id:'local',pos:player.toArray(),state}]};if(action.kind==='attack'){hitMob(mobs,action.id,state,player.toArray(),Date.now(),ctx);syncState(state);return true;}if(action.kind==='interactMob'){toast(interactMob(mobs,action.id,state,player.toArray(),'local'));syncState(state);save();return true;}if(action.kind==='dismount'){state.riding=null;for(const m of mobs)if(m.rider==='local')m.rider=null;return true;}if(action.kind==='spawnMob'){const egg=heldKey()?.split(':').map(Number),type=state.mode==='creative'&&action.mob?action.mob:egg?.[0]===383?EGG_TYPES[egg[1]]:null;if(!MOB_TYPES[type]||!worldValid(...action.at)||mobs.filter(m=>m.hp>0).length>=150)throw Error('소환할 수 없습니다.');mobs.push(spawnMob(type,action.at[0]+.5,action.at[2]+.5,get,undefined,action.at[1]));if(state.mode!=='creative')S.take(state.slots,slot);syncState(state);save();return true;}if(action.kind==='portal'){if(heldKey()==='259:0'){if(!lightNetherPortal(get,setBlock,action.at))throw Error('내부 2×3, 바깥 4×5 흑요석 틀이 필요합니다.');if(state.mode!=='creative'){state.slots[slot].wear=(state.slots[slot].wear||0)+1;if(state.slots[slot].wear>=64)state.slots[slot]=null;}}else if(heldKey()==='381:0'){if(!fillEndFrame(get,setBlock,action.at))throw Error('엔드 차원문 틀에 사용하세요.');if(state.mode!=='creative')S.take(state.slots,slot);}syncState(state);save();return true;}applyAction(state,action,{get,set:setBlock,pos:player.toArray(),now:Date.now(),chests,furnaces,mobs});syncState(state);save();return true}catch(e){toast(e.message);return false;}}
function updateVitals(){$('#touchFly').hidden=state.mode!=='creative';const v=$('#vitals');v.hidden=!current||state.mode==='creative';if(!v.hidden){drawMeter($('#armor'),armorPoints(state),'armor');$('#armor').hidden=armorPoints(state)===0;$('#air').hidden=(state.air??300)>=300;drawMeter($('#air'),Math.max(0,(state.air??300)/15),'air');drawMeter($('#hearts'),state.hp,'heart');drawMeter($('#hunger'),state.hunger,'food');$('#xp-fill').style.width=(state.xp%20)*5+'%';$('#xp-level').textContent=Math.floor(state.xp/20)||'';}}

function death(){if(screen==='죽었습니다!')return;const c=panel('죽었습니다!',false);text(c,'현재 버전은 리스폰 시 아이템을 유지합니다.');row(c).append(button('리스폰',()=>{operate({kind:'respawn'});if(roomCode)return;if(dimensionName!=='overworld')changeDimension('overworld',true);if(state.spawn)player.fromArray(state.spawn);else player.fromArray(chunkWorld.spawn);state.fallTop=null;velY=0;resume()}),button('타이틀 화면',()=>{save();disconnect();main()}));}
let inventoryAt=null,inventoryType='bag',craftCells=Array(4).fill(null),pickedSlot=null,recipeSearch='',recipePage=0;
function inventory(at=null,type='bag'){inventoryAt=at;inventoryType=type;craftCells=Array(type==='craft'?9:4).fill(null);pickedSlot=null;renderInventory();}
function stackButton(v,fn,label='빈 슬롯'){const b=button('',fn);b.className='slot';b.title=v?itemName(v.key)+' ×'+v.count:label;b.setAttribute('aria-label',b.title);if(v){b.innerHTML=`<img class="block-icon" src="${itemIcon(v.key)}" alt=""><small>${v.count>1?v.count:''}</small>`;if(v.wear){const d=S.item(v.key);const bar=document.createElement('div');bar.className='durability';bar.style.width=Math.max(0,100-v.wear/(d.maxDurability||1)*100)+'%';b.append(bar);}}return b;}
function renderInventory(){const title={bag:'인벤토리',craft:'제작',furnace:'화로',chest:'상자'}[inventoryType],c=panel(title,false);c.closest('.panel').classList.add('inventory-panel');const top=document.createElement('div');top.className='crafting-area';c.append(top);
if(inventoryType==='furnace'){const f=furnaces[inventoryAt.join(',')]||newFurnace();const layout=document.createElement('div');layout.className='furnace-layout';for(const [i,label]of [[0,'재료'],[1,'연료'],[2,'제련 결과']]){const b=stackButton(f.slots[i],()=>{const from=pickedSlot;pickedSlot=null;operate({kind:'furnace',at:inventoryAt,slot:i,from});},label);b.classList.add('furnace-slot-'+i);layout.append(b);}const fire=document.createElement('div');fire.className='furnace-flame';fire.style.setProperty('--burn',Math.round(f.burn/Math.max(1,f.burnTotal)*100)+'%');fire.title='남은 연료 '+f.burn.toFixed(1)+'초';layout.append(fire);const arrow=document.createElement('div');arrow.className='furnace-progress';arrow.style.setProperty('--cook',f.cook*10+'%');arrow.title=f.cook.toFixed(1)+' / 10초';layout.append(arrow);top.append(layout);}

else if(inventoryType==='chest'){const grid=document.createElement('div');grid.className='storage-grid';const storage=chests[inventoryAt.join(',')]||Array(27).fill(null);storage.forEach((v,i)=>grid.append(stackButton(v,()=>operate({kind:'chest',at:inventoryAt,slot:i,direction:v?'out':'in'}))));top.append(grid);text(top,'빈 상자칸: 현재 손 아이템 넣기 / 아이템 클릭: 꺼내기');}
else {if(inventoryType==='bag'){const equipment=document.createElement('div');equipment.className='equipment';['머리','몸통','다리','발'].forEach((name,i)=>{const b=stackButton(state.armor?.[i],()=>{const from=pickedSlot;pickedSlot=null;operate({kind:'equip',from,slot:i})},name);if(!state.armor?.[i])b.dataset.empty=name;equipment.append(b);});const figure=document.createElement('div');figure.className='inventory-character';figure.innerHTML='<i class=character-head></i><i class=character-body></i><i class=character-arm-left></i><i class=character-arm-right></i><i class=character-leg-left></i><i class=character-leg-right></i>';top.append(equipment,figure);}const grid=document.createElement('div');const width=inventoryType==='craft'?3:2;grid.className='craft-grid craft-width-'+width;grid.style.gridTemplateColumns=`repeat(${width},40px)`;craftCells.forEach((source,i)=>{const v=source===null?null:state.slots[source];grid.append(stackButton(v,()=>{craftCells[i]=pickedSlot;renderInventory();},'제작칸'));});top.append(grid);const arrow=document.createElement('span');arrow.textContent='→';arrow.className='craft-arrow';top.append(arrow);const match=S.matchRecipe(craftCells.map(i=>i===null?null:state.slots[i]),width);top.append(stackButton(match?{key:S.key(match.recipe.result.id,match.recipe.result.metadata||0),count:match.recipe.result.count,wear:match.recipe.result.wear}:null,()=>{if(operate({kind:'craft',indices:craftCells,width,at:inventoryAt})){pickedSlot=null;}},'제작 결과'));}
text(c,pickedSlot!==null?`${itemName(state.slots[pickedSlot]?.key)} 선택됨 — 이동할 슬롯 또는 제작칸을 누르세요.`:'아이템 클릭 → 다른 슬롯으로 이동. 우클릭은 절반 이동.');const bag=document.createElement('div');bag.className='storage-grid';c.append(bag);const order=[...Array.from({length:27},(_,i)=>i+9),...Array.from({length:9},(_,i)=>i)];for(const i of order){const b=stackButton(state.slots[i],()=>{if(pickedSlot===null){if(state.slots[i])pickedSlot=i;renderInventory();}else if(pickedSlot===i){pickedSlot=null;renderInventory();}else{const from=pickedSlot;pickedSlot=null;operate({kind:'moveStack',from,to:i});}});if(i<9)b.classList.add('quick-slot');if(i===pickedSlot)b.classList.add('active');b.oncontextmenu=e=>{e.preventDefault();if(pickedSlot!==null){const from=pickedSlot;pickedSlot=null;operate({kind:'moveStack',from,to:i,split:true})}};bag.append(b);}
const actions=row(c);actions.append(button('조합법',recipeMenu),button('완료',resume));if(state.mode==='creative')actions.prepend(button('생물 소환',mobCatalog),button('아이템 검색',creativeCatalog));}
function creativeCatalog(){const c=panel('아이템 검색',false);c.closest('.panel').classList.add('inventory-panel');const q=field(c,'이름 또는 아이템 ID',recipeSearch);const list=document.createElement('div');list.className='catalog-grid';c.append(list);function draw(){list.innerHTML='';const query=q.value.toLowerCase();let count=0;for(const d of S.catalog.items){const variants=d.variations?.length?d.variations:[{metadata:0,displayName:d.displayName}];for(const v of variants){const k=S.key(d.id,v.metadata);if(!(itemName(k)+' '+d.name+' '+d.id+' '+v.displayName).toLowerCase().includes(query))continue;if(++count>180)break;list.append(stackButton({key:k,count:d.stackSize||64},()=>{operate({kind:'creative',key:k});toast(itemName(k)+' 선택');},v.displayName));}}}q.oninput=()=>{recipeSearch=q.value;draw()};draw();text(c,'아이템 데이터 전체 검색. 설치·사용 기능은 구현된 종류에만 적용됩니다.');c.append(button('완료',()=>renderInventory()));q.focus();}
function recipeMenu(){const c=panel('조합법');const q=field(c,'아이템 이름 또는 ID',recipeSearch);const list=document.createElement('div');list.className='recipe-list';c.append(list);const pager=row(c);let page=recipePage;const info=text(c,'');function draw(){list.innerHTML='';const query=q.value.toLowerCase();const matches=S.recipes.map((r,i)=>({r,i})).filter(({r})=>{const k=S.key(r.result.id,r.result.metadata||0);return (itemName(k)+' '+S.item(k)?.name+' '+r.result.id).toLowerCase().includes(query)});page=Math.min(page,Math.max(0,Math.ceil(matches.length/8)-1));for(const {r}of matches.slice(page*8,page*8+8)){const card=document.createElement('div');card.className='recipe-card';const k=S.key(r.result.id,r.result.metadata||0);text(card,itemName(k)+' ×'+r.result.count);const line=row(card);const g=document.createElement('div');g.className='recipe-grid';const entries=r.inShape?Array.from({length:9},(_,i)=>r.inShape[Math.floor(i/3)]?.[i%3]):[...r.ingredients,...Array(9-r.ingredients.length).fill(null)];entries.forEach(v=>{const n=S.normalizeIngredient(v);g.append(stackButton(n?{key:S.key(n.id,n.metadata??0),count:1}:null,()=>{}));});line.append(g);const result=stackButton({key:k,count:r.result.count},()=>{});line.append(result);list.append(card);}info.textContent=`${matches.length}개 조합 · ${page+1}/${Math.max(1,Math.ceil(matches.length/8))}`;recipePage=page;}q.oninput=()=>{recipeSearch=q.value;page=0;draw()};pager.append(button('이전',()=>{page=Math.max(0,page-1);draw()}),button('다음',()=>{page++;draw()}),button('완료',renderInventory));draw();}
