function multiMenu(){const c=panel('멀티플레이');text(c,'친구가 LAN 서버 열기에 입력한 숫자를 그대로 입력하세요.');const name=field(c,'플레이어 이름',read('akzm-name','Player')),code=field(c,'서버 번호 (4~12자리 숫자)','','text');code.inputMode='numeric';code.maxLength=12;const err=text(c,'','error');row(c).append(button('서버 접속',()=>connect('join',code.value,name.value,err)),button('취소',main));text(c,'서버를 여는 사람은 싱글플레이 → 세계 입장 → Esc → LAN 서버 열기를 선택하세요.');}
function lanMenu(){const c=panel('LAN 서버 열기',false),name=field(c,'플레이어 이름',read('akzm-name','Player')),code=field(c,'서버 번호 (4~12자리 숫자)',String(Math.floor(1000+Math.random()*9000)));code.inputMode='numeric';code.maxLength=12;text(c,'친구에게 이 번호를 알려주세요. 방장이 나가면 방이 닫히며 변경 사항은 방장 브라우저에 저장됩니다.');const err=text(c,'','error');row(c).append(button('LAN 세계 시작',()=>{save();connect('host',code.value,name.value,err)}),button('취소',pause));}
function transmit(o){if(ws?.readyState===1)ws.send(JSON.stringify(o));}
function connect(type,code,name,err){if(!/^\d{4,12}$/.test(code)){err.textContent='4~12자리 숫자를 입력하세요.';return;}if(ws){err.textContent='연결을 진행 중입니다.';return;}err.textContent='서버 연결 중...';localStorage.setItem('akzm-name',name.slice(0,20));const configured=read('akzm-server-url','');if(!configured&&location.hostname.endsWith('.github.io')){err.textContent='설정 → 멀티플레이 서버에서 서버 주소를 입력하세요.';return;}const endpoint=new URL(configured||location.origin);endpoint.protocol=endpoint.protocol==='https:'||endpoint.protocol==='wss:'?'wss:':'ws:';endpoint.pathname='/';const socket=ws=new WebSocket(endpoint.href);let accepted=false;const timeout=setTimeout(()=>{if(!accepted){err.textContent='서버 연결 시간이 초과되었습니다.';socket.close();}},15000);socket.onopen=()=>socket.send(JSON.stringify({type,code,name,...(type==='host'?{seed:current.seed,flat:current.flat,generator:current.generator,dimension:dimensionName,dimensions:current.dimensions,pos:player.toArray(),mobs,mode:state.mode,state,chests,furnaces,time:worldTime,edits:[...edits]}:{})}));socket.onerror=()=>{err.textContent='서버에 연결할 수 없습니다.';};socket.onmessage=e=>{const m=JSON.parse(e.data);switch(m.type){case 'hello':myId=m.id;break;case 'error':err.textContent=m.message;if(!accepted)socket.close();break;case 'joined':accepted=true;clearTimeout(timeout);roomCode=m.code;isHost=m.host;receiveDimension(m);toast('서버 '+code+'에 연결되었습니다.');break;case 'dimension':receiveDimension(m);toast(DIMENSIONS[dimensionName].name+'에 들어왔습니다.');break;case 'universe':if(current&&isHost)current.dimensions=m.dimensions;break;case 'weather':weather=m.weather;break;case 'teleport':player.fromArray(m.pos);velY=0;if(screen==='죽었습니다!'&&state.hp>0)resume();break;case 'mobs':mobs=m.mobs;projectiles=m.projectiles||[];break;case 'state':syncState(m.state);if(m.time!==undefined)worldTime=m.time;break;case 'actionError':toast(m.message);syncState(m.state);break;case 'furnaces':furnaces=m.furnaces;if(screen==='화로')renderInventory();break;case 'chests':chests=m.chests;if(screen==='상자')renderInventory();break;case 'player':if(m.id!==myId)remote(m);break;case 'left':removeRemote(m.id);break;case 'block':if(!m.dimension||m.dimension===dimensionName)setBlock(m.x,m.y,m.z,m.b);break;case 'chat':chatLines.push(m.name+': '+m.text);chatLines=chatLines.slice(-5);$('#notice').textContent=chatLines.join('\n');break;case 'pong':ping=Date.now()-m.time;break;case 'closed':toast(m.message);if(current){const c=panel('서버 연결 종료');text(c,m.message);row(c).append(button('세계 사본 저장',()=>{current.id=Date.now();current.name+=' 사본';current.remote=false;current.edits=[...edits];worlds.push(current);persist();disconnect();main()}),button('메인 메뉴',()=>{disconnect();main()}));}break;}};socket.onclose=()=>{clearTimeout(timeout);if(ws===socket){ws=null;roomCode='';isHost=false;for(const id of [...remotes.keys()])removeRemote(id);if(accepted&&screen==='game'){pause();toast('서버 연결이 끊겼습니다. 현재 세계는 내보낼 수 있습니다.');}}};}
function disconnect(){if(ws){const old=ws;ws=null;old.close();}roomCode='';isHost=false;for(const id of [...remotes.keys()])removeRemote(id);chatLines=[];$('#notice').textContent='';}
function receiveDimension(m){for(const id of [...remotes.keys()])removeRemote(id);const w=isHost?current:{id:Date.now(),name:'멀티플레이 '+m.code,remote:true};Object.assign(w,{seed:m.seed,flat:m.flat,generator:m.generator,dimension:m.dimension,mode:m.state.mode,state:m.state,edits:m.edits,chests:m.chests,furnaces:m.furnaces,mobs:m.mobs,weather:m.weather,pos:m.pos.slice(0,3),time:m.time});loadWorld(w,!isHost);projectiles=m.projectiles||[];for(const p of m.players)remote(p);}
function changeDimension(name,admin=false){if(!DIMENSIONS[name]||name===dimensionName)return;save();if(roomCode){operate({kind:'travel',dimension:name});return;}if(!admin){const b=portalAt(get,player.toArray());const expected=b===45?(dimensionName==='nether'?'overworld':'nether'):b===46?(dimensionName==='end'?'overworld':'end'):null;if(expected!==name)return;}const saved=current.dimensions[name]||{};Object.assign(current,{dimension:name,edits:saved.edits||[],chests:saved.chests,furnaces:saved.furnaces,mobs:saved.mobs,pos:saved.pos,weather:saved.weather||'clear',state});state.fallTop=null;state.riding=null;loadWorld(current);save();toast(DIMENSIONS[name].name+'에 들어왔습니다.');}
function updatePortal(dt){const b=portalAt(get,player.toArray());if(!b){portalArmed=true;portalWait=0;return;}if(!portalArmed)return;portalWait+=dt;if(portalWait>=(state.mode==='creative'?.3:b===46?.3:4)){portalArmed=false;changeDimension(b===45?(dimensionName==='nether'?'overworld':'nether'):(dimensionName==='end'?'overworld':'end'));}}
function dimensionsMenu(){const c=panel('차원 이동',false);text(c,'크리에이티브 차원 이동');for(const [id,d]of Object.entries(DIMENSIONS))c.append(button(d.name,()=>changeDimension(id,true),id===dimensionName));c.append(button('완료',pause));}
function mobCatalog(){const c=panel('생물 소환',false),list=document.createElement('div');list.className='mob-catalog';c.append(list);for(const [type,d]of Object.entries(MOB_TYPES)){list.append(button(d.name,()=>{const dir=new T.Vector3();camera.getWorldDirection(dir);const pos=player.clone().addScaledVector(dir,3);const at=[Math.floor(pos.x),Math.floor(player.y-1),Math.floor(pos.z)];if(operate({kind:'spawnMob',mob:type,at}))resume();}));}c.append(button('완료',renderInventory));}
function clearMobs(){for(const g of mobVisuals.values()){scene.remove(g);g.traverse(o=>{o.geometry?.dispose();o.material?.dispose();});}mobVisuals.clear();}
const shotVisuals=new Map();
function drawMobs(dt){const alive=new Set();for(const m of mobs){if(m.hp<=0)continue;alive.add(m.id);let g=mobVisuals.get(m.id);const variant=[m.size,m.baby,m.sheared,m.tamed,m.saddled].join(':');if(g&&g.userData.variant!==variant){disposeVisual(g);mobVisuals.delete(m.id);g=null;}if(!g){g=createMobModel(m);g.position.set(m.x,m.y,m.z);scene.add(g);mobVisuals.set(m.id,g);}animateMob(g,m,timer,dt);g.traverse(o=>{if(o.material?.emissive)o.material.emissive.setHex(m.hurtFor>0?0x8b1111:0);});}for(const [id,g]of mobVisuals)if(!alive.has(id)){disposeVisual(g);mobVisuals.delete(id);}const shots=new Set();for(const p of projectiles){shots.add(p.id);let mesh=shotVisuals.get(p.id);if(!mesh){mesh=new T.Mesh(new T.BoxGeometry(p.kind==='arrow'?.07:.22,.12,p.kind==='arrow'?.7:.22),new T.MeshBasicMaterial({color:p.kind==='arrow'?0xb5a088:p.kind==='potion'?0x9c4fbd:p.kind==='snowball'?0xffffff:0xff8d24}));scene.add(mesh);shotVisuals.set(p.id,mesh);}mesh.position.fromArray(p.pos);mesh.lookAt(new T.Vector3(...p.pos).add(new T.Vector3(...p.velocity)));}for(const [id,g]of shotVisuals)if(!shots.has(id)){disposeVisual(g);shotVisuals.delete(id);}const bosses=mobs.filter(m=>m.hp>0&&MOB_TYPES[m.type]?.boss);$('#bossbar').hidden=!current||!bosses.length;if(bosses.length){const boss=bosses[0];$('#boss-name').textContent=MOB_TYPES[boss.type].name;$('#boss-fill').style.width=Math.max(0,boss.hp/MOB_TYPES[boss.type].hp*100)+'%';}}
function disposeVisual(g){scene.remove(g);g.traverse(o=>{o.geometry?.dispose();if(Array.isArray(o.material))o.material.forEach(m=>m.dispose());else o.material?.dispose();});}

function aimMob(){const direction=new T.Vector3();camera.getWorldDirection(direction);return targetMob(mobs,MOB_TYPES,player.toArray(),direction.toArray(),4,(a,b)=>!lineOfSight(get,a,b))?.id||null;}

function remote(m){let r=remotes.get(m.id);if(!r){const group=new T.Group(),skin=new T.MeshLambertMaterial({color:0xc89e7a}),shirt=new T.MeshLambertMaterial({color:0x42b7b0}),pants=new T.MeshLambertMaterial({color:0x4c4c95});for(const [sz,pos,ma]of [[[.5,.5,.5],[0,-.15,0],skin],[[.55,.65,.3],[0,-.72,0],shirt],[[.22,.65,.25],[-.15,-1.36,0],pants],[[.22,.65,.25],[.15,-1.36,0],pants],[[.2,.65,.25],[-.39,-.72,0],skin],[[.2,.65,.25],[.39,-.72,0],skin]]){let mesh=new T.Mesh(new T.BoxGeometry(...sz),ma);mesh.position.set(...pos);group.add(mesh);}scene.add(group);r={group,target:new T.Vector3(32,20,32),yaw:0};remotes.set(m.id,r);}if(m.pos){r.target.fromArray(m.pos);r.yaw=m.pos[3];}}
function removeRemote(id){const r=remotes.get(id);if(r){scene.remove(r.group);r.group.traverse(o=>{o.geometry?.dispose();o.material?.dispose()});remotes.delete(id);}}
function message(text){chatLines.push(text);chatLines=chatLines.slice(-5);$('#notice').textContent=chatLines.join('\n');}
function chat(initial=''){const c=panel('채팅 / 명령어',false);ui.classList.add('chat-mode');hud.hidden=false;const i=field(c,'메시지 또는 명령어',initial),feedback=text(c,'');i.maxLength=512;i.autocomplete='off';i.autocapitalize='off';i.spellcheck=false;const send=()=>{const value=i.value.trim();if(!value)return;if(value.startsWith('/')){if(roomCode)transmit({type:'command',text:value});else try{message(runCommand(value,state,{seed:current.seed,pos:player.toArray(),time:worldTime,now:Date.now(),mobs,structures,dimension:dimensionName,travel:to=>changeDimension(to,true),get,set:setBlock,setTime:t=>worldTime=t,setWeather:w=>weather=w,teleport:p=>{player.fromArray(p);velY=0;}}));syncState(state);save();}catch(e){feedback.textContent=e.message;feedback.className='error';return;}}else if(roomCode)transmit({type:'chat',text:value});else message('Player: '+value);resume();if(state.hp<=0)death();};i.onkeydown=e=>{e.stopPropagation();if(e.key==='Enter'){e.preventDefault();send();}if(e.key==='Escape')resume();};const examples=document.createElement('div');examples.className='command-examples';for(const cmd of ['/help','/gamemode creative','/gamemode survival','/time set day','/give @p diamond_sword 1','/summon Zombie ~ ~ ~3','/tp ~ ~5 ~'])examples.append(button(cmd,()=>{i.value=cmd;i.focus();}));c.append(examples);row(c).append(button('적용 / 보내기',send),button('닫기',resume));text(c,'싱글플레이: 바로 적용 · 멀티플레이: 방장 명령어 사용');i.focus();}

function ray(){const dir=new T.Vector3();camera.getWorldDirection(dir);let prev=null;for(let t=0;t<(state.mode==='creative'?5:4.5);t+=.02){const p=camera.position.clone().addScaledVector(dir,t),v=[Math.floor(p.x),Math.floor(p.y),Math.floor(p.z)];if(worldValid(...v)&&get(...v)&&!((heldKey()==='325:0'?[45,46]:[21,44,45,46]).includes(get(...v))))return{hit:v,prev};prev=v;}return null;}
function act(place){if(screen!=='game')return;if(!place){const id=aimMob();if(id){swing=1;operate({kind:'attack',id});return;}}if(place){const mob=aimMob();if(mob){operate({kind:'interactMob',id:mob});return;}}const t=ray();if(place&&armorInfo(heldKey())){operate({kind:'equip',from:slot,slot:armorInfo(heldKey()).slot});return;}if(place&&heldKey()&&(S.foods[S.parse(heldKey())[0]]||S.parse(heldKey())[0]===335)){operate({kind:'eat'});return;}if(!t)return;if(place&&['325:0','326:0','327:0'].includes(heldKey())){operate({kind:'bucket',at:heldKey()==='325:0'?t.hit:t.prev});return;}if(!place&&state.mode==='creative'&&S.item(heldKey())?.name.endsWith('_sword'))return;if(place&&heldKey()==='259:0'&&t.prev){operate({kind:'portal',at:t.prev});return;}if(place&&heldKey()==='381:0'&&get(...t.hit)===47){operate({kind:'portal',at:t.hit});return;}if(place&&S.parse(heldKey())[0]===383&&t.prev){operate({kind:'spawnMob',at:t.prev});return;}swing=1;if(place){const b=get(...t.hit);if(!keys[settings.keys.down]&&[23,25,26].includes(b)){inventory(t.hit,{23:'craft',25:'furnace',26:'chest'}[b]);return;}if(t.prev)operate({kind:'place',at:t.prev});}else if(state.mode==='creative')operate({kind:'mine',at:t.hit});else {mining={at:t.hit,started:performance.now(),block:get(...t.hit),key:heldKey()};operate({kind:'startMine',at:t.hit});}}
function stopMining(){mineHold=false;mining=null;cracks.visible=false;$('#mining').hidden=true;if(roomCode)transmit({type:'action',action:{kind:'cancelMine'}});else state.mining=null;}
function updateMining(now){cracks.visible=false;if(placeHold&&screen==='game'&&now-lastUse>=200){lastUse=now;act(true);}if(!mineHold||screen!=='game'){mining=null;$('#mining').hidden=true;return;}if(state.mode==='creative'){if(now>=nextMine){act(false);nextMine=now+200;}return;}if(now<nextMine)return;const victim=aimMob();if(victim){mining=null;act(false);nextMine=now+350;return;}const t=ray();if(!t){mining=null;$('#mining').hidden=true;return;}if(!mining||mining.at.join(',')!==t.hit.join(',')||mining.key!==heldKey())act(false);if(!mining)return;const time=miningTime(mining.block,mining.key,false)*1000,progress=time===0?1:Math.min(1,(now-mining.started)/time);$('#mining').hidden=true;cracks.position.set(...mining.at.map(v=>v+.5));cracks.visible=progress>0;cracks.material.map=crackTexture(Math.min(9,Math.floor(progress*10)));swing=.4+Math.sin(now/80)*.2;if(progress>=1){const at=mining.at;mining=null;operate({kind:'mine',at});nextMine=now+(time===0?0:250);cracks.visible=false;}}

function collide(p){for(let x=Math.floor(p.x-.28);x<=Math.floor(p.x+.28);x++)for(let y=Math.floor(p.y-1.62);y<=Math.floor(p.y+.12);y++)for(let z=Math.floor(p.z-.28);z<=Math.floor(p.z+.28);z++){const b=get(x,y,z);if(isSolid(b)){const boxes=extraBounds.get(b);if(!boxes)return true;for(const box of boxes)if(p.x+.28>x+box.min[0]&&p.x-.28<x+box.max[0]&&p.y+.12>y+box.min[1]&&p.y-1.62<y+box.max[1]&&p.z+.28>z+box.min[2]&&p.z-.28<z+box.max[2])return true;}}return false;}
function movement(dt){const k=settings.keys,forward=(keys[k.forward]?1:0)-(keys[k.back]?1:0),side=(keys[k.right]?1:0)-(keys[k.left]?1:0);const inWater=get(Math.floor(player.x),Math.floor(player.y-1),Math.floor(player.z))===21;if(state.riding&&keys[k.down])operate({kind:'dismount'});let speed=flying?10:state.riding?8:inWater?2.2:keys[k.down]?2:5;const length=Math.hypot(forward,side)||1,dx=(-Math.sin(yaw)*forward+Math.cos(yaw)*side)*speed*dt/length,dz=(-Math.cos(yaw)*forward-Math.sin(yaw)*side)*speed*dt/length;for(const [axis,amount]of [['x',dx],['z',dz]]){let p=player.clone();p[axis]+=amount;if(Math.abs(p[axis])<WORLD_LIMIT-1&&!collide(p))player.copy(p);}if(state.mode==='survival')flying=false;if(flying)velY=((keys[k.jump]?1:0)-(keys[k.down]?1:0))*8;else if(inWater){velY=Math.max(-2,velY-4*dt);if(keys[k.jump])velY=3;}else{velY-=22*dt;if(ground&&keys[k.jump])velY=8;}const vertical=velY*dt,steps=Math.max(1,Math.ceil(Math.abs(vertical)/.08));ground=false;for(let step=0;step<steps;step++){const p=player.clone();p.y+=vertical/steps;if(!collide(p))player.copy(p);else{ground=velY<0;velY=0;break;}}player.y=Math.min(256,player.y);if(player.y<-8){if(state.mode==='creative')player.fromArray(chunkWorld.spawn);else{state.hp=0;if(roomCode)transmit({type:'action',action:{kind:'void'}});death();}}}
canvas.addEventListener('mousedown',e=>{if(screen!=='game'||settings.touch)return;if(!document.pointerLockElement){canvas.requestPointerLock?.();return;}if(e.button===1){const t=ray();if(t&&state.mode==='creative')operate({kind:'creative',key:blockItems[get(...t.hit)]});return;}if(e.button===0){mineHold=true;nextMine=performance.now()+200;act(false);}if(e.button===2){placeHold=true;lastUse=performance.now();act(true);}});document.addEventListener('mouseup',e=>{if(e.button===0)stopMining();if(e.button===2)placeHold=false;});canvas.oncontextmenu=e=>e.preventDefault();document.addEventListener('mousemove',e=>{if(screen==='game'&&document.pointerLockElement){yaw-=e.movementX*.00005*settings.sensitivity;pitch-=e.movementY*.00005*settings.sensitivity*(settings.invert?-1:1);pitch=Math.max(-1.5,Math.min(1.5,pitch));}});
document.addEventListener('pointerlockchange',()=>{if(!document.pointerLockElement&&screen==='game'&&!settings.touch)pause()});
document.addEventListener('keydown',e=>{if(bindKey){e.preventDefault();settings.keys[bindKey.key]=e.code;const done=bindKey.done;bindKey=null;applySettings();done();return;}if(e.target.tagName==='INPUT')return;if(e.code==='F3'){e.preventDefault();debug=!debug;$('#info').style.display=debug?'block':'none';return;}if(e.code==='Escape'){if(current){e.preventDefault();screen==='game'?pause():resume()}return;}if(/Digit[1-9]/.test(e.code)){chooseSlot(Number(e.code.slice(-1))-1);}if(screen!=='game')return;e.preventDefault();keys[e.code]=true;if(e.repeat)return;if(e.code===settings.keys.inventory)inventory();if(e.code===settings.keys.fly)toggleFlight();if(e.code===settings.keys.jump){const now=performance.now();if(now-lastJumpPress<280)toggleFlight();lastJumpPress=now;}if(e.code===settings.keys.chat)chat();if(e.code==='Slash')chat('/');});document.addEventListener('keyup',e=>keys[e.code]=false);window.addEventListener('blur',()=>{keys={};if(screen==='game')pause()});document.addEventListener('wheel',e=>{if(screen==='game'){chooseSlot((slot+(e.deltaY>0?1:8))%9);}},{passive:true});
let lastJumpPress=-Infinity;function toggleFlight(){if(state.mode!=='creative')return;flying=!flying;velY=0;state.fallTop=null;toast(flying?'비행 켜짐 · 점프 상승 / 웅크리기 하강':'비행 꺼짐');}$('#touchFly').onclick=toggleFlight;
for(const b of document.querySelectorAll('[data-key]')){b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys[settings.keys[b.dataset.key]||b.dataset.key]=true;if(b.dataset.key==='jump'){const now=performance.now();if(now-lastJumpPress<280)toggleFlight();lastJumpPress=now;}};b.onpointerup=b.onpointercancel=()=>keys[settings.keys[b.dataset.key]||b.dataset.key]=false;}
$('#touchBreak').onpointerdown=e=>{e.preventDefault();e.currentTarget.setPointerCapture(e.pointerId);mineHold=true;nextMine=performance.now()+200;act(false);};$('#touchBreak').onpointerup=$('#touchBreak').onpointercancel=$('#touchBreak').onlostpointercapture=stopMining;$('#touchPlace').onpointerdown=e=>{e.preventDefault();e.currentTarget.setPointerCapture(e.pointerId);placeHold=true;lastUse=performance.now();act(true);};$('#touchPlace').onpointerup=$('#touchPlace').onpointercancel=$('#touchPlace').onlostpointercapture=()=>placeHold=false;$('#touchChat').onclick=()=>chat();$('#touchCommands').onclick=()=>chat('/');$('#touchMenu').onclick=pause;$('#touchInv').onclick=inventory;const resetTouchLook=attachTouchLook(canvas,()=>settings.touch&&screen==='game',(dx,dy)=>{const sensitivity=.0001*settings.sensitivity;yaw-=dx*sensitivity;pitch=Math.max(-1.5,Math.min(1.5,pitch-dy*sensitivity*(settings.invert?-1:1)));},{tap:()=>act(!aimMob()),start:()=>{mineHold=true;nextMine=performance.now()+200;act(false);},end:stopMining});window.addEventListener('blur',()=>{resetTouchLook();keys={};placeHold=false;stopMining();});


window.addEventListener('resize',()=>{handCamera.aspect=innerWidth/innerHeight;handCamera.updateProjectionMatrix();camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();applySettings()});window.addEventListener('beforeunload',save);setInterval(()=>{if(current)save();if(roomCode)transmit({type:'ping',time:Date.now()});},5000);
let last=performance.now();function frame(now){requestAnimationFrame(frame);const dt=Math.min((now-last)/1000,.04);last=now;timer+=dt;if(current){if(!roomCode&&['game','인벤토리','제작','화로','상자','아이템 검색','조합법'].includes(screen)){const smeltBefore=state.smelting?.remaining;tickSurvival(state,dt,Object.values(keys).some(Boolean));tickFurnaces(furnaces,dt,get);tickEnvironment(state,dt,get,player.toArray());if(smeltBefore!==state.smelting?.remaining)updateHotbar();tickMobs(mobs,dt,get,[{id:'local',pos:player.toArray(),look:[yaw,pitch],state}],worldTime,{dimension:dimensionName,projectiles,set:setBlock});if(state.hp<=0)death();worldTime=(worldTime+dt*20)%24000;updateVitals();}if(screen==='game'){updateMining(now);movement(dt);streamChunks();updatePortal(dt);if(!roomCode)tickEnvironment(state,0,get,player.toArray());camera.position.copy(player);if(settings.bob&&!flying&&(keys[settings.keys.forward]||keys[settings.keys.back]))camera.position.y+=Math.sin(timer*12)*.025;camera.rotation.set(pitch,yaw,0);target=ray();outline.visible=!!target;if(target)outline.position.set(...target.hit.map(v=>v+.5));if(now-lastMove>60&&roomCode){transmit({type:'move',pos:[player.x,player.y,player.z,yaw,pitch]});lastMove=now;}$('#info').textContent=(roomCode?`서버 ${roomCode} · ${remotes.size+1}명 · ${ping}ms`:'싱글플레이 · '+(state.mode==='survival'?'서바이벌':'크리에이티브'))+`\n${DIMENSIONS[dimensionName].name} · XYZ ${player.x.toFixed(1)} / ${player.y.toFixed(1)} / ${player.z.toFixed(1)}\n${heldKey()?itemName(heldKey()):'빈 손'}${flying?' · 비행':''}`;}else{outline.visible=false;if(!roomCode&&screen==='화로'&&Math.floor(timer*2)!==Math.floor((timer-dt)*2))renderInventory();}}else{camera.position.set(32+Math.sin(timer*.035)*15,23,32+Math.cos(timer*.035)*15);camera.lookAt(32,12,32);outline.visible=false;}rain.visible=!!current&&dimensionName==='overworld'&&weather!=='clear';if(rain.visible){rain.position.set(player.x,player.y-5,player.z);for(let i=0;i<600;i++)rainPositions[i*3+1]=(rainPositions[i*3+1]-dt*12+30)%30;rainGeo.attributes.position.needsUpdate=true;}drawMobs(dt);for(const r of remotes.values()){r.group.position.lerp(r.target,Math.min(1,dt*14));r.group.rotation.y=r.yaw;}if(current){const light=Math.max(.08,Math.sin((worldTime/24000)*Math.PI*2)*.5+.5);scene.background.setRGB(.12+light*.38,.16+light*.52,.25+light*.6);scene.fog.color.copy(scene.background);sun.intensity=.15+light*.65;if(weather!=='clear'){scene.background.multiplyScalar(.6);scene.fog.color.copy(scene.background);sun.intensity*=.5;}}if(current&&dimensionName!=='overworld'){scene.background.set(DIMENSIONS[dimensionName].sky);scene.fog.color.copy(scene.background);sun.intensity=dimensionName==='nether'?.7:.45;}clouds.visible=settings.clouds&&(!current||dimensionName==='overworld');clouds.position.x=Math.sin(timer*.015)*4;for(const key of dirtyChunks)meshChunk(...key.split(',').map(Number));dirtyChunks.clear();renderer.render(scene,camera);if(current&&screen==='game'){updateHeld();swing=Math.max(0,swing-dt*4);const walking=keys[settings.keys.forward]||keys[settings.keys.back]||keys[settings.keys.left]||keys[settings.keys.right];heldBlock.position.set(.48-Math.sin(swing*Math.PI)*.16,-.38-Math.sin(swing*Math.PI)*.12+(walking&&settings.bob?Math.sin(timer*12)*.015:0),-.9);heldBlock.rotation.z=.1-Math.sin(swing*Math.PI)*.5;renderer.autoClear=false;renderer.clearDepth();renderer.render(handScene,handCamera);renderer.autoClear=true;}if(Math.floor(timer*5)!==Math.floor((timer-dt)*5)){waterMat.color.setHSL(.57,.12,.85+Math.sin(timer*2)*.06);}}
applySettings();main();requestAnimationFrame(frame);
